using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEditor;using CrossTheLine;
public static class WholeGameVisualAudit{
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(JourneyGame g,string n,params object[] a)=>typeof(JourneyGame).GetMethod(n,F).Invoke(g,a);
 static Dictionary<Sprite,Rect> boxes=new Dictionary<Sprite,Rect>();static HashSet<Sprite> characters;
 static Rect Visible(Sprite s){if(boxes.TryGetValue(s,out var b))return b;try{var t=s.texture;var p=t.GetPixels32();int x0=(int)s.rect.xMax,y0=(int)s.rect.yMax,x1=-1,y1=-1;for(int y=(int)s.rect.y;y<(int)s.rect.yMax;y++)for(int x=(int)s.rect.x;x<(int)s.rect.xMax;x++)if(p[y*t.width+x].a>=200){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}b=new Rect((x0-s.rect.x-s.pivot.x)/s.pixelsPerUnit,(y0-s.rect.y-s.pivot.y)/s.pixelsPerUnit,(x1-x0+1)/s.pixelsPerUnit,(y1-y0+1)/s.pixelsPerUnit);}catch{var v=JourneySpriteAssets.VisibleBounds(s);b=new Rect(v.min.x,v.min.y,v.size.x,v.size.y);}boxes[s]=b;return b;}
 static Bounds World(SpriteRenderer r){var b=Visible(r.sprite);Vector3 a=r.transform.TransformPoint(new Vector3(r.flipX?-b.xMax:b.xMin,r.flipY?-b.yMax:b.yMin));Vector3 z=r.transform.TransformPoint(new Vector3(r.flipX?-b.xMin:b.xMax,r.flipY?-b.yMin:b.yMax));var box=new Bounds();box.SetMinMax(Vector3.Min(a,z),Vector3.Max(a,z));return box;}
 static string Name(SpriteRenderer r)=>r.transform.parent.name+"/"+r.name;
 public static async Task<string> Run(){var g=UnityEngine.Object.FindAnyObjectByType<JourneyGame>();var w=g.GetComponent<JourneyContinuousWorld>();if(!Application.isPlaying)throw new Exception("Play required");float speed=Time.timeScale;bool saving=JourneySceneFlow.TestWithoutSaving;try{JourneySceneFlow.TestWithoutSaving=true;Time.timeScale=0;
  var catalog=JourneyAssets.Load<JourneySpriteCatalog>("CrossTheLine/JourneySpriteCatalog");characters=catalog.items.Where(i=>i.character).Select(i=>i.pixel).Where(s=>s).ToHashSet();foreach(var s in g.jesusFrames.Concat(g.disciples).Concat(g.supportingCast))characters.Add(s);var hero=JourneyAssets.Load<GameObject>("CrossTheLine/Characters/Jesus").GetComponent<JourneyCharacterView>();characters.Add(hero.idle);foreach(var s in hero.walkFrames)characters.Add(s);var book=JsonUtility.FromJson<StoryBook>(g.storySource.text);var overlaps=new List<string>{"chapter\tstep\tactorA\tactorB\tintersectionFraction\tfootDelta\txA\tyA\txB\tyB"};var feet=new List<string>{"chapter\tstep\tactor\tvisibleFootMinusRoot\tsprite"};var summary=new List<string>();int states=0,actors=0;
  for(int chapter=0;chapter<book.chapters.Length;chapter++)for(int step=0;step<book.chapters[chapter].steps.Length;step++){
   w.Normalize();Call(g,"ClearStoryPanels");typeof(JourneyGame).GetField("save",F).SetValue(g,new JourneySave{chapter=chapter,step=step,unlocked=26});typeof(JourneyGame).GetField("started",F).SetValue(g,true);Call(g,"CloseMenu");Call(g,"LoadWorld",false);await Task.Yield();await Task.Yield();w.Normalize();
   var cast=g.GetComponentsInChildren<SpriteRenderer>().Where(r=>r.enabled&&r.sprite&&r.color.a>.5f&&r.gameObject.activeInHierarchy&&characters.Contains(r.sprite)).Where(r=>!r.name.Contains("Portrait")&&!r.name.Contains("초상")&&r.bounds.size.y<4.5f).ToArray();
   int missing=cast.Count(r=>!r.sprite||!r.sharedMaterial);summary.Add($"{chapter+1}\t{step}\t{cast.Length}\t{missing}");states++;actors+=cast.Length;
   foreach(var r in cast){var b=World(r);if(r.name=="Sprite"&&r.transform.parent&&Mathf.Abs(b.min.y-r.transform.parent.position.y)>.12f)feet.Add($"{chapter+1}\t{step}\t{Name(r)}\t{b.min.y-r.transform.parent.position.y:F3}\t{r.sprite.name}\tpos={r.transform.localPosition};scale={r.transform.localScale};rawMin={Visible(r.sprite).yMin};catalogMin={JourneySpriteAssets.VisibleBounds(r.sprite).min.y}");}
   for(int a=0;a<cast.Length;a++)for(int b=a+1;b<cast.Length;b++){
    var x=World(cast[a]);var y=World(cast[b]);float dx=Mathf.Min(x.max.x,y.max.x)-Mathf.Max(x.min.x,y.min.x),dy=Mathf.Min(x.max.y,y.max.y)-Mathf.Max(x.min.y,y.min.y);if(dx<=0||dy<=0)continue;
    float fraction=dx*dy/Mathf.Min(x.size.x*x.size.y,y.size.x*y.size.y);if(fraction<.18f)continue;
    overlaps.Add($"{chapter+1}\t{step}\t{Name(cast[a])}\t{Name(cast[b])}\t{fraction:F3}\t{Mathf.Abs(x.min.y-y.min.y):F3}\t{x.center.x:F2}\t{x.min.y:F2}\t{y.center.x:F2}\t{y.min.y:F2}");
   }
  }
  Directory.CreateDirectory("Docs/QA/WholeGame");File.WriteAllLines("Docs/QA/WholeGame/OverlapCandidates.tsv",overlaps);File.WriteAllLines("Docs/QA/WholeGame/FootCandidates.tsv",feet);File.WriteAllLines("Docs/QA/WholeGame/StoryStates.tsv",new[]{"chapter\tstep\tactors\tmissingMaterial"}.Concat(summary));return $"Audited {states} states, {actors} actor instances: {overlaps.Count-1} overlap and {feet.Count-1} foot-offset candidates for review.";}finally{Time.timeScale=speed>0?speed:1;JourneySceneFlow.TestWithoutSaving=saving;}
 }
}

